import { Link, NavLink, Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import { useEffect, useRef, useState, type FormEvent } from 'react'
import { useTournament, useTournaments } from '../state/TournamentContext'
import { useAuth } from '../state/AuthContext'
import { LandingPage } from '../pages/LandingPage'
import { insertPlayers, loadAllTournaments, loadPublicTournament, persistPlayer, removeRemotePlayer } from '../data/tournamentRepository'
import { loadAdminOverview, updateProfileRole, type AdminOverview, type AppRole, type AssignableRole } from '../data/adminRepository'
import { createManagedUser, deleteManagedUser, listManagedUsers, updateManagedUser, type ManagedUser } from '../data/adminUsersRepository'
import type { Tournament } from '../domain/types'
import { Database, Eye, EyeOff, ExternalLink, Home as HomeIcon, Info, LogOut, Play, RefreshCw, ShieldCheck, Skull, Square, Trash2, Trophy, Users } from 'lucide-react'
import { Modal } from '../components/ui/modal'
import { showToast, ToastViewport } from '../components/ui/toast'
import { defaultScoring, uid, type Pod, type ScoringRules } from '../domain/types'

const primary = 'rounded-lg bg-amber-400 px-4 py-2 font-bold text-slate-950 hover:bg-amber-300 disabled:cursor-not-allowed disabled:opacity-50'
const panel = 'rounded-xl border border-slate-700/70 bg-slate-900/75 p-5 shadow-xl shadow-slate-950/20'
const field = 'mt-1 w-full rounded-lg border border-slate-600 bg-slate-950 px-3 py-2 text-slate-100 outline-none focus:border-amber-400'
const statusColor: Record<string, string> = { borrador: 'bg-slate-600', activa: 'bg-emerald-600', completada: 'bg-blue-600', activo: 'bg-emerald-600', finalizado: 'bg-violet-600' }
const statusLabel: Record<string,string> = { borrador:'En espera' }
function Badge({ children }: { children: string }) { return <span className={`inline-flex h-6 items-center rounded-md border border-slate-500 px-2 text-xs font-semibold leading-none ${statusColor[children] ?? 'bg-slate-600'}`}>{statusLabel[children] ?? children}</span> }
function RoundTimer({ round }: { round: Tournament['rounds'][number] }) { const [now,setNow]=useState(0); useEffect(()=>{if(round.status!=='activa'||!round.startedAt)return;const update=()=>setNow(Date.now());update();const interval=window.setInterval(update,1000);return()=>window.clearInterval(interval)},[round.status,round.startedAt]); if(!round.startedAt)return null; const elapsed=Math.max(0,(round.endedAt?Date.parse(round.endedAt):now)-Date.parse(round.startedAt)); const hours=Math.floor(elapsed/3_600_000); const minutes=Math.floor(elapsed%3_600_000/60_000); const seconds=Math.floor(elapsed%60_000/1_000); const clock=[hours,minutes,seconds].map(value=>String(value).padStart(2,'0')).join(':'); return <span className="round-timer text-sm font-semibold tabular-nums text-amber-300">Tiempo {clock}</span> }
function Notice({ children, error = false }: { children: React.ReactNode; error?: boolean }) { const shown=useRef<{children:React.ReactNode;error:boolean}|undefined>(undefined); useEffect(()=>{const previous=shown.current;if(previous&&previous.children===children&&previous.error===error)return;shown.current={children,error};showToast(children,error)},[children,error]); return null }
function ConfirmModal({ title, description, confirmLabel='Confirmar', destructive=false, onClose, onConfirm }: { title:string; description:string; confirmLabel?:string; destructive?:boolean; onClose:()=>void; onConfirm:()=>void }) { return <Modal title={title} description={description} onClose={onClose}><div className="flex flex-wrap justify-end gap-3"><button type="button" className="rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800" onClick={onClose}>Cancelar</button><button type="button" className={destructive ? 'rounded-lg bg-red-700 px-4 py-2 text-sm font-bold text-white hover:bg-red-600' : primary} onClick={onConfirm}>{confirmLabel}</button></div></Modal> }

function Header() { const { user, configured, isAdmin, signOut } = useAuth(); const navigate = useNavigate(); const location = useLocation(); const authScreen = ['/login', '/register', '/forgot-password', '/auth/confirmed'].includes(location.pathname); return <header className="border-b border-slate-700/70 bg-slate-950/80"><div className="mx-auto flex max-w-6xl items-center justify-between px-4 py-4"><Link to="/" className="inline-flex items-center gap-2 text-lg font-black tracking-tight text-amber-300"><HomeIcon size={18} />Home</Link>{!authScreen && <nav className="flex flex-wrap justify-end gap-3 text-sm"><Link to="/dashboard" className="inline-flex items-center gap-1.5 rounded-md px-2 py-1 hover:bg-slate-800"><Trophy size={15} />Mis torneos</Link>{isAdmin&&<Link to="/admin" className="inline-flex items-center gap-1.5 rounded-md px-2 py-1 text-amber-300 hover:bg-slate-800"><ShieldCheck size={15} />Administración</Link>}{configured && user ? <button className="inline-flex items-center gap-1.5 rounded-md px-2 py-1 hover:bg-slate-800" onClick={() => void signOut().catch(() => undefined).finally(() => navigate('/', { replace: true }))}><LogOut size={15} />Cerrar sesión</button> : <Link to="/login" className="inline-flex items-center gap-1.5 rounded-md px-2 py-1 hover:bg-slate-800"><Trophy size={15} />Organizador</Link>}</nav>}</div></header> }
function CompletionRedirect() { const { id } = useParams(); const tournament = useTournament(id); const location = useLocation(); const navigate = useNavigate(); useEffect(() => { if (tournament && location.pathname.endsWith('/rounds') && sessionStorage.getItem('mesa-mayor.completed-tournament') === tournament.id) { sessionStorage.removeItem('mesa-mayor.completed-tournament'); navigate(`/tournaments/${tournament.id}/standings`, { replace: true }) } }, [tournament, location.pathname, navigate]); return null }
function Layout({ children }: { children: React.ReactNode }) { return <><Header /><CompletionRedirect /><main className="mx-auto min-h-[calc(100vh-65px)] w-full max-w-6xl px-4 py-8">{children}</main><ToastViewport /></> }
export function AppRouter() { return <Routes><Route path="/" element={<LandingPage />} /><Route path="/login" element={<Auth title="Inicia sesión" />} /><Route path="/register" element={<Auth title="Crea tu cuenta" />} /><Route path="/forgot-password" element={<Auth title="Recupera tu contraseña" />} /><Route path="/auth/confirmed" element={<ConfirmedAccount />} /><Route path="/dashboard" element={<Dashboard />} /><Route path="/admin" element={<AdminRoute />} /><Route path="/tournaments/new" element={<NewTournament />} /><Route path="/tournaments/:id/*" element={<TournamentLayout />}><Route index element={<Overview />} /><Route path="players" element={<Players />} /><Route path="rounds" element={<Rounds />} /><Route path="standings" element={<Standings />} /><Route path="settings" element={<Settings />} /></Route><Route path="/t/:slug" element={<PublicView />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes> }

function Home() { return <Layout><section className="card-pattern overflow-hidden rounded-2xl border border-amber-300/30 bg-slate-900 px-6 py-18 text-center sm:px-12"><p className="mb-4 text-sm font-bold tracking-[.2em] text-amber-300">TORNEOS MULTIJUGADOR</p><h1 className="mx-auto max-w-3xl text-4xl font-black tracking-tight sm:text-6xl">Organiza la próxima gran mesa.</h1><p className="mx-auto mt-5 max-w-xl text-lg text-slate-300">Rondas justas, resultados ágiles y clasificación clara para Commander y cualquier TCG multijugador.</p><div className="mt-8 flex flex-wrap justify-center gap-3"><Link className={primary} to="/register">Crear cuenta</Link><Link className="rounded-lg border border-slate-500 px-4 py-2 font-semibold hover:bg-slate-800" to="/login">Iniciar sesión</Link></div></section><section className="mt-6 grid gap-4 md:grid-cols-3">{[['♟','Mesas equilibradas','Distribución válida de 3 y 4 jugadores.'],['✦','Resultados claros','Puntos, kills y desempates trazables.'],['⌁','Consulta pública','Comparte el estado sin exponer controles.']].map(([icon,title,text]) => <article key={title} className={panel}><span className="text-2xl text-amber-300">{icon}</span><h2 className="mt-3 font-bold">{title}</h2><p className="mt-1 text-sm text-slate-300">{text}</p></article>)}</section></Layout> }
function Auth({ title }: { title: string }) { const { configured, user, signIn, signUp, resetPassword } = useAuth(); const navigate=useNavigate(); const [message,setMessage]=useState(''); const [busy,setBusy]=useState(false); const [showPassword,setShowPassword]=useState(false); const recovery=title==='Recupera tu contraseña'; const register=title==='Crea tu cuenta'; useEffect(()=>{if(register&&user)navigate('/dashboard',{replace:true})},[register,user,navigate]); async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const email=String(data.get('email')).trim();const password=String(data.get('password'));setBusy(true);setMessage('');try{if(recovery){await resetPassword(email);setMessage('Revisa tu correo para continuar con la recuperación.')}else if(register){const name=String(data.get('name')).trim();if(password!==String(data.get('confirmPassword')))throw new Error('Las contraseñas no coinciden.');await signUp(name,email,password);/* setMessage('Cuenta creada. Revisa tu correo para confirmar tu cuenta; esta pestaña entrará al panel automáticamente.'); // Restaurar al reactivar Confirm email en Supabase. */navigate('/dashboard',{replace:true})}else{await signIn(email,password);navigate('/dashboard')}}catch(error){setMessage(error instanceof Error?error.message:'No se pudo completar la operación.')}finally{setBusy(false)}} const passwordField=(name:string,label:string)=><label className="block text-sm font-medium">{label}<span className="relative mt-1 block"><input required name={name} minLength={6} type={showPassword?'text':'password'} className={`${field} mt-0 pr-12`} /><button type="button" aria-label={showPassword?'Ocultar contraseña':'Mostrar contraseña'} title={showPassword?'Ocultar contraseña':'Mostrar contraseña'} className="absolute inset-y-0 right-0 inline-flex w-11 items-center justify-center text-slate-400 hover:text-amber-300" onClick={()=>setShowPassword(value=>!value)}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></span></label>; return <Layout><div className="mx-auto max-w-md"><div className={panel}><h1 className="text-2xl font-black">{title}</h1><p className="mt-2 text-sm text-slate-300">{configured ? '' : 'Configura Supabase para activar el acceso real; el modo demo no requiere cuenta.'}</p>{message&&<div className="mt-4"><Notice error={!message.includes('Revisa')&&!message.includes('creada')}>{message}</Notice></div>}<form className="mt-5 space-y-4" onSubmit={submit}>{register&&<label className="block text-sm font-medium">Nombre<input required name="name" autoComplete="name" className={field} placeholder="Tu nombre" /></label>}<label className="block text-sm font-medium">Correo<input required name="email" type="email" autoComplete="email" className={field} placeholder="correo@gmail.com" /></label>{!recovery&&<>{passwordField('password','Contraseña')}{register&&passwordField('confirmPassword','Confirmar contraseña')}</>}<button disabled={busy} className={`${primary} w-full`}>{busy?'Procesando…':recovery?'Enviar instrucciones':'Continuar'}</button></form><Link className="mt-5 block text-center text-sm text-amber-300 underline" to={title==='Inicia sesión'?'/register':'/login'}>{title==='Inicia sesión'?'¿No tienes cuenta? Regístrate':'Volver al inicio de sesión'}</Link>{!recovery&&<Link className="mx-auto mt-3 inline-flex w-full justify-center rounded-lg border border-slate-500 px-3 py-2 text-sm font-semibold text-slate-300 hover:bg-slate-800" to="/forgot-password">Olvidé mi contraseña</Link>}</div></div></Layout> }
function ConfirmedAccount() { const { user, loading } = useAuth(); return <Layout><div className="mx-auto max-w-md text-center"><section className={panel}><span className="text-4xl">✓</span><h1 className="mt-3 text-2xl font-black">{loading ? 'Confirmando tu cuenta…' : user ? '¡Cuenta confirmada!' : 'Revisa la confirmación'}</h1><p className="mt-3 text-slate-300">{user ? 'Ya puedes cerrar esta pestaña y volver a la ventana original. Entrarás al panel automáticamente.' : 'Estamos validando el enlace. Espera un momento o vuelve a abrir el enlace del correo.'}</p>{user&&<button type="button" className={`${primary} mt-5`} onClick={() => window.close()}>Cerrar pestaña</button>}</section></div></Layout> }
function Dashboard() { const { tournaments,ready,remoteError,removeTournament } = useTournaments(); const { configured,user,loading }=useAuth(); const [tournamentToDelete,setTournamentToDelete]=useState<Tournament>(); const [creating,setCreating]=useState(false); const navigate=useNavigate(); const ownTournaments=tournaments.filter(tournament=>tournament.ownerId===user?.id); if(configured&&!loading&&!user)return <Navigate to="/login" replace/>; return <Layout><div className="mb-6 flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm text-amber-300">Panel de {String(user?.user_metadata.display_name ?? 'organizador')}</p><h1 className="text-3xl font-black">Mis torneos</h1></div><button className={primary} onClick={() => setCreating(true)}>+ Nuevo torneo</button></div>{!ready&&<p className="mb-4 text-sm text-slate-300">Cargando tus torneos…</p>}{remoteError&&<div className="mb-4"><Notice error>{remoteError}</Notice></div>}{(['activo','finalizado'] as const).map(status => <section key={status} className="mb-7"><h2 className="mb-3 text-lg font-bold">{status === 'activo' ? 'Activos' : 'Finalizados'}</h2><div className="grid gap-3 md:grid-cols-2">{ownTournaments.filter(t => t.status === status).map(t => <article key={t.id} role="link" tabIndex={0} className={`${panel} cursor-pointer transition hover:-translate-y-0.5 hover:border-amber-400`} onClick={event=>{if(!(event.target as HTMLElement).closest('button'))navigate(`/tournaments/${t.id}`)}} onKeyDown={event=>{if(event.key==='Enter')navigate(`/tournaments/${t.id}`)}}><div className="flex justify-between gap-2"><strong>{t.name}</strong><Badge>{t.status}</Badge></div><p className="mt-2 text-sm text-slate-300">{t.format} · {t.players.filter(p => p.active).length} activos · {t.rounds.length}/{t.plannedRounds} rondas</p><div className="mt-3 flex justify-end"><button className="text-sm text-red-300 underline" onClick={() => setTournamentToDelete(t)}>Eliminar</button></div></article>)}{ready&&!ownTournaments.some(t => t.status === status) && <p className="text-sm text-slate-400">Aún no hay torneos en este estado.</p>}</div></section>)}{creating && <TournamentCreateModal onClose={() => setCreating(false)} />}{tournamentToDelete && <ConfirmModal title="Eliminar torneo" description={`Eliminarás “${tournamentToDelete.name}” y todas sus rondas, mesas y resultados. Esta acción no se puede deshacer.`} confirmLabel="Eliminar torneo" destructive onClose={() => setTournamentToDelete(undefined)} onConfirm={() => { removeTournament(tournamentToDelete.id); setTournamentToDelete(undefined) }} />}</Layout> }

function TournamentCreateModal({ onClose }: { onClose:()=>void }) { const { createTournament }=useTournaments(); const navigate=useNavigate(); const [error,setError]=useState(''); function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const plannedRounds=Number(form.get('rounds'));if(!Number.isInteger(plannedRounds)||plannedRounds<1){setError('La cantidad de rondas debe ser un entero positivo.');return}const scoring=Object.fromEntries(['first','second','third','fourth','tie'].map(key=>[key,Number(form.get(key))])) as unknown as ScoringRules;if(Object.values(scoring).some(value=>!Number.isInteger(value)||value<0)){setError('Todos los puntos deben ser enteros iguales o mayores que cero.');return}const tournament=createTournament({name:String(form.get('name')),format:String(form.get('format')),plannedRounds,isPublic:true,scoring});onClose();navigate(`/tournaments/${tournament.id}`)} return <Modal title="Nuevo torneo" description="Define lo básico ahora; podrás ajustar la configuración después." onClose={onClose}><form className="space-y-4" onSubmit={submit}>{error&&<Notice error>{error}</Notice>}<div className="grid gap-3 sm:grid-cols-2"><label className="text-sm sm:col-span-2">Nombre<input autoFocus required name="name" className={field} placeholder="Commander de sábado" /></label><label className="text-sm">Formato<input name="format" defaultValue="Commander" className={field} /></label><label className="text-sm">Rondas<input required name="rounds" defaultValue="3" min="1" type="number" className={field} /></label></div><fieldset><legend className="text-sm font-bold">Puntuación</legend><div className="mt-2 space-y-2">{[['first','Primer lugar'],['second','Segundo lugar'],['third','Tercer lugar'],['fourth','Cuarto lugar'],['tie','Empate (jugador vivo)']].map(([key,label])=><label className="flex items-center justify-between gap-4 text-xs" key={key}><span>{label}</span><input className="w-24 rounded-md border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" name={key} min="0" type="number" defaultValue={defaultScoring[key as keyof ScoringRules]} /></label>)}</div></fieldset><div className="flex justify-end gap-3"><button type="button" className="rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800" onClick={onClose}>Cancelar</button><button className={primary}>Crear torneo</button></div></form></Modal> }
function NewTournament() { const { createTournament } = useTournaments(); const navigate = useNavigate(); const [error, setError] = useState(''); function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const values = new FormData(event.currentTarget); const rounds = Number(values.get('rounds')); if (!Number.isInteger(rounds) || rounds < 1) return setError('La cantidad de rondas debe ser un entero positivo.'); const scoring = Object.fromEntries(['first','second','third','fourth','tie'].map(key => [key, Number(values.get(key))])) as unknown as ScoringRules; if (Object.values(scoring).some(value => !Number.isInteger(value) || value < 0)) return setError('Todos los puntos deben ser enteros iguales o mayores que cero.'); const tournament = createTournament({ name: String(values.get('name')), format: String(values.get('format')), plannedRounds: rounds, isPublic: true, scoring }); navigate(`/tournaments/${tournament.id}`) } return <Layout><div className="mx-auto max-w-2xl"><h1 className="mb-5 text-3xl font-black">Nuevo torneo</h1><form onSubmit={submit} className={`${panel} space-y-4`}>{error && <Notice error>{error}</Notice>}<div className="grid gap-4 sm:grid-cols-2"><label className="text-sm">Nombre<input required name="name" className={field} placeholder="Commander de sábado" /></label><label className="text-sm">Juego o formato<input name="format" defaultValue="Commander" className={field} /></label><label className="text-sm">Rondas planificadas<input required name="rounds" defaultValue="3" min="1" type="number" className={field} /></label></div><fieldset><legend className="mb-2 font-bold">Reglas de puntuación</legend><div className="space-y-2">{[['first','Primer lugar'],['second','Segundo lugar'],['third','Tercer lugar'],['fourth','Cuarto lugar'],['tie','Empate (jugador vivo)']].map(([key,label]) => <label key={key} className="flex items-center justify-between gap-4 text-xs text-slate-300"><span>{label}</span><input name={key} type="number" min="0" defaultValue={defaultScoring[key as keyof ScoringRules]} className="w-28 rounded-md border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" /></label>)}</div></fieldset><button className={primary}>Crear torneo</button></form></div></Layout> }

function TournamentLayout() { const { id } = useParams(); const tournament = useTournament(id); if (!tournament) return <Layout><Notice error>Torneo no encontrado.</Notice></Layout>; const base = `/tournaments/${tournament.id}`; return <Layout><div className="mb-6 flex flex-wrap justify-between gap-3"><div><p className="text-sm text-amber-300">{tournament.format}</p><h1 className="text-3xl font-black">{tournament.name}</h1></div><Badge>{tournament.status}</Badge></div><nav className="mb-6 flex gap-1 overflow-x-auto rounded-lg border border-slate-700 bg-slate-900 p-1">{[['', 'Resumen'],['players','Jugadores'],['rounds','Rondas'],['standings','Clasificación'],['settings','Configuración']].map(([suffix,label]) => <NavLink end={!suffix} className={({isActive}) => `whitespace-nowrap rounded-md px-3 py-2 text-sm ${isActive ? 'bg-amber-400 font-bold text-slate-950' : 'hover:bg-slate-800'}`} key={label} to={`${base}${suffix ? `/${suffix}` : ''}`}>{label}</NavLink>)}</nav><Routes><Route index element={<Overview />} /><Route path="players" element={<Players />} /><Route path="rounds" element={<Rounds />} /><Route path="standings" element={<Standings />} /><Route path="settings" element={<Settings />} /></Routes></Layout> }
function Current() { const { id } = useParams(); const tournament = useTournament(id); if (!tournament) throw new Error('Torneo no encontrado'); return tournament }
function Overview() { const tournament = Current(); const current = tournament.rounds.at(-1); return <section className={panel}><h2 className="text-xl font-bold">Estado del torneo</h2><div className="mt-4 grid grid-cols-3 gap-3 text-center"><Metric label="Jugadores activos" value={tournament.players.filter(p => p.active).length} /><Metric label="Rondas" value={`${tournament.rounds.length}/${tournament.plannedRounds}`} /><Metric label="Mesa actual" value={current ? `R${current.number}` : '—'} /></div>{current && <div className="mt-5 rounded-lg bg-slate-950 p-4"><p className="font-bold">Ronda {current.number} <span className="ml-2"><Badge>{current.status}</Badge></span></p><p className="mt-2 text-sm text-slate-300">{current.pods.length} mesas generadas. {current.status === 'completada' ? 'Resultados registrados.' : 'Registra los resultados de cada mesa.'}</p><Link className="mt-3 inline-flex items-center gap-2 rounded-lg bg-amber-400 px-3 py-2 text-sm font-bold text-slate-950 hover:bg-amber-300" to="rounds"><Play size={15} />Ir a rondas</Link></div>}</section> }
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="rounded-lg bg-slate-950 p-3"><strong className="block text-xl text-amber-300">{value}</strong><span className="text-xs text-slate-400">{label}</span></div> }
function Players() { const tournament = Current(); const { id } = useParams(); const { addPlayers, togglePlayer, removePlayer, renamePlayer } = useTournaments(); const [message,setMessage] = useState(''); const [adding,setAdding]=useState(false); const [search,setSearch]=useState(''); const [editing,setEditing]=useState<Tournament['players'][number]>(); const [pending,setPending]=useState<{player:Tournament['players'][number];action:'toggle'|'delete'}>(); function add(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const result = addPlayers(id!, String(new FormData(event.currentTarget).get('names')).split('\n')); setMessage(result.added ? `${result.added} jugador(es) agregado(s).${result.duplicate ? ` Se omitió duplicado: ${result.duplicate}.` : ''}` : result.duplicate ? `No se agregó ningún jugador; “${result.duplicate}” ya existe.` : 'Escribe al menos un nombre.'); setAdding(false) } function edit(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!editing)return;const result=renamePlayer(id!,editing.id,String(new FormData(event.currentTarget).get('name')));setMessage(result??'Nombre actualizado.');if(!result)setEditing(undefined)} const normalizedSearch=search.trim().toLocaleLowerCase(); const filteredPlayers=tournament.players.filter(player=>player.name.toLocaleLowerCase().includes(normalizedSearch)); return <section><div className={panel}><div className="mb-3 flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-bold">Jugadores</h2><span className="text-sm text-slate-300">{tournament.players.filter(p => p.active).length} activos</span></div><button disabled={tournament.status === 'finalizado'} className={primary} onClick={() => setAdding(true)}>+ Agregar jugadores</button></div>{message && <Notice>{message}</Notice>}<label className="mb-3 block"><span className="sr-only">Buscar jugadores</span><input type="search" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Buscar jugadores..." className={`${field} mt-0`} /></label><div className="max-h-[22rem] space-y-2 overflow-y-auto pr-2">{filteredPlayers.map(player => <div key={player.id} className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-slate-950 p-3"><div><strong>{player.name}</strong><span className={`ml-2 text-xs ${player.active ? 'text-emerald-300' : 'text-slate-400'}`}>{player.active ? 'Activo' : 'Retirado'}</span></div><div className="flex gap-2"><button className="text-xs text-amber-300 underline" onClick={() => setEditing(player)}>Editar</button><button className="text-xs text-slate-300 underline" onClick={() => setPending({player,action:'toggle'})}>{player.active ? 'Retirar' : 'Activar'}</button><button className="text-xs text-red-300 underline" onClick={() => setPending({player,action:'delete'})}>Eliminar</button></div></div>)}{!filteredPlayers.length && <p className="text-sm text-slate-400">{search ? 'No se encontraron jugadores.' : 'Aún no hay jugadores.'}</p>}</div></div>{adding && <Modal title="Agregar jugadores" description="Escribe un nombre por línea. No se permiten nombres repetidos." onClose={() => setAdding(false)}><form className="space-y-4" onSubmit={add}><textarea required name="names" className={field} rows={7} placeholder={'Ana\nBruno\nCarla'} /><div className="flex justify-end gap-3"><button type="button" className="rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800" onClick={() => setAdding(false)}>Cancelar</button><button className={primary}>Agregar</button></div></form></Modal>}{editing && <Modal title="Editar jugador" description="Actualiza el nombre del participante." onClose={() => setEditing(undefined)}><form className="space-y-4" onSubmit={edit}><label className="block text-sm">Nombre<input autoFocus required name="name" defaultValue={editing.name} className={field} /></label><div className="flex justify-end gap-3"><button type="button" className="rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800" onClick={() => setEditing(undefined)}>Cancelar</button><button className={primary}>Guardar</button></div></form></Modal>}{pending && <ConfirmModal title={pending.action==='delete'?'Eliminar jugador':pending.player.active?'Retirar jugador':'Activar jugador'} description={pending.action==='delete' ? `¿Eliminar a ${pending.player.name}? No se puede eliminar a alguien que ya esté en una ronda.` : pending.player.active ? `${pending.player.name} no se incluirá en las próximas rondas.` : `${pending.player.name} volverá a incluirse en las próximas rondas.`} confirmLabel={pending.action==='delete'?'Eliminar':'Confirmar'} destructive={pending.action==='delete'} onClose={() => setPending(undefined)} onConfirm={() => { const result=pending.action==='delete'?removePlayer(id!,pending.player.id):(togglePlayer(id!,pending.player.id),undefined); setMessage(result??(pending.action==='delete'?'Jugador eliminado.':pending.player.active?'Jugador retirado.':'Jugador activado.')); setPending(undefined) }} />}</section> }

function Rounds() {
  const tournament = Current()
  const { id } = useParams()
  const { generateRound, deleteLastRound, startRound, completeRound } = useTournaments()
  const [message,setMessage] = useState('')
  const [deletingLast,setDeletingLast] = useState(false)
  const [roundToComplete,setRoundToComplete] = useState<Tournament['rounds'][number]>()
  const [selectedRoundId,setSelectedRoundId] = useState<string>()
  const last = tournament.rounds.at(-1)
  const hasOpenRound = tournament.rounds.some(round=>round.status!=='completada')
  const names = Object.fromEntries(tournament.players.map(player => [player.id,player.name]))
  const selectedRound = tournament.rounds.find(round=>round.id===selectedRoundId) ?? last
  const selectedIndex = selectedRound ? tournament.rounds.findIndex(round=>round.id===selectedRound.id) : -1

  useEffect(()=>{ setSelectedRoundId(tournament.rounds.at(-1)?.id) },[tournament.rounds.length])

  return <section>
    <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
      <h2 className="text-xl font-bold">Rondas y mesas</h2>
      <div className="flex flex-wrap justify-end gap-2">
        <button disabled={selectedIndex<=0} className="rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-50" onClick={()=>setSelectedRoundId(tournament.rounds[selectedIndex-1].id)}>Anterior</button>
        <button disabled={selectedIndex>=tournament.rounds.length-1} className="rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-50" onClick={()=>setSelectedRoundId(tournament.rounds[selectedIndex+1].id)}>Siguiente</button>
        <button disabled={tournament.status === 'finalizado' || hasOpenRound || tournament.rounds.length>=tournament.plannedRounds} className={`${primary} inline-flex items-center gap-2`} onClick={() => setMessage(generateRound(id!) ?? 'Ronda generada. Iníciala cuando las mesas estén listas.')}><RefreshCw size={16} />Generar siguiente ronda</button>
        <button disabled={!last} className="inline-flex items-center gap-2 rounded-lg border border-red-700 px-3 py-2 text-sm text-red-200 hover:bg-red-950 disabled:cursor-not-allowed disabled:opacity-50" onClick={() => setDeletingLast(true)}><Trash2 size={16} />Eliminar última</button>
      </div>
    </div>
    {message && <Notice error={message.includes('requieren') || message.includes('Completa') || message.includes('finalizado') || message.includes('Primero') || message.includes('Espera')}>{message}</Notice>}
    {selectedRound ? <article className={panel}>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-3"><h3 className="font-bold">Ronda {selectedRound.number} <span className="ml-2"><Badge>{selectedRound.status}</Badge></span></h3><RoundTimer round={selectedRound} /></div>
        <div className="flex flex-wrap gap-2">
          <Link className="inline-flex items-center gap-2 rounded-lg border border-slate-500 px-3 py-2 text-sm font-semibold hover:bg-slate-800" to={`/t/${tournament.publicSlug}`} target="_blank" rel="noreferrer"><Eye size={16} />Vista pública<ExternalLink size={14} /></Link>
          <button disabled={selectedRound.status !== 'borrador' || tournament.status === 'finalizado'} className="inline-flex items-center gap-2 rounded-lg bg-emerald-600 px-3 py-2 text-sm font-bold text-white hover:bg-emerald-500 disabled:cursor-not-allowed disabled:opacity-50" onClick={() => setMessage(startRound(id!,selectedRound.id) ?? 'Ronda iniciada. El cronómetro está en marcha.')}><Play size={16} fill="currentColor" />Iniciar ronda</button>
          <button disabled={selectedRound.status !== 'activa' || tournament.status === 'finalizado'} className="inline-flex items-center gap-2 rounded-lg bg-red-700 px-3 py-2 text-sm font-bold text-white hover:bg-red-600 disabled:cursor-not-allowed disabled:opacity-50" onClick={() => setRoundToComplete(selectedRound)}><Square size={15} fill="currentColor" />Terminar ronda</button>
        </div>
      </div>
      {selectedRound.status==='borrador' && <p className="mt-3 text-sm text-slate-300">Mesas generadas. Inicia la ronda para habilitar el registro de resultados.</p>}
      <div className="mt-4 grid gap-3 md:grid-cols-2">{selectedRound.pods.map(pod => <PodCard key={pod.id} tournamentId={id!} roundId={selectedRound.id} pod={pod} readOnly={tournament.status === 'finalizado' || selectedRound.status !== 'activa'} names={names} editable={selectedRound.status === 'activa'} />)}</div>
    </article> : <div className={`${panel} text-sm text-slate-300`}>No hay rondas todavía. Agrega al menos tres jugadores activos y genera la primera.</div>}
    {deletingLast && last && <ConfirmModal title="Eliminar última ronda" description={last.pods.some(p=>p.results?.length) ? 'Se eliminarán las mesas y resultados de esta ronda. Esta acción no se puede deshacer.' : 'Se eliminarán las mesas de esta ronda.'} confirmLabel="Eliminar ronda" destructive onClose={() => setDeletingLast(false)} onConfirm={() => { setMessage(deleteLastRound(id!) ?? 'Última ronda eliminada y clasificación recalculada.'); setDeletingLast(false) }} />}
    {roundToComplete && <ConfirmModal title={`Terminar ronda ${roundToComplete.number}`} description="La ronda se bloqueará después de validar todos los resultados y guardar el tiempo transcurrido." confirmLabel="Terminar ronda" destructive onClose={() => setRoundToComplete(undefined)} onConfirm={() => { setMessage(completeRound(id!,roundToComplete.id) ?? 'Ronda terminada. La clasificación se actualizó.'); setRoundToComplete(undefined) }} />}
  </section>
}function PodCard({ tournamentId, roundId, pod, names, readOnly, editable }: { tournamentId: string; roundId: string; pod: Pod; names: Record<string,string>; readOnly:boolean; editable:boolean }) { const { savePod } = useTournaments(); const [message,setMessage] = useState(''); const [resultType,setResultType] = useState<NonNullable<Pod['resultType']>>(pod.resultType ?? 'normal'); const [deadPlayers,setDeadPlayers]=useState<Set<string>>(()=>new Set(pod.results?.filter(result=>result.dead).map(result=>result.playerId))); const isTie=resultType==='empate'; function toggleDead(playerId:string){setDeadPlayers(current=>{const next=new Set(current);if(next.has(playerId))next.delete(playerId);else next.add(playerId);return next})} function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const next: Pod = { ...pod, resultType, results: pod.playerIds.map(playerId => ({ playerId, position:isTie ? 1 : Number(form.get(`position-${playerId}`)), kills:isTie ? 0 : Number(form.get(`kills-${playerId}`)), dead:isTie&&deadPlayers.has(playerId) })) }; setMessage(savePod(tournamentId,roundId,pod.id,next) ?? 'Resultado guardado. La clasificación se actualizó.') } return <div className="rounded-lg border border-slate-700 bg-slate-950 p-4"><h4 className="font-bold text-amber-300">Mesa {pod.number}</h4>{!editable && <div className="mt-3 grid gap-2">{pod.playerIds.map(playerId=>{const result=pod.results?.find(item=>item.playerId===playerId);return <section className="overflow-hidden rounded-lg border border-slate-700 bg-slate-900" key={playerId}><h5 className="px-3 py-2 text-sm font-semibold">{names[playerId]}{result?.dead&&<span className="ml-2 inline-flex text-red-300" title="Murió durante el empate"><Skull size={15} /></span>}</h5>{result?<div className="grid grid-cols-2 border-t border-slate-700 text-xs"><p className="border-r border-slate-700 px-3 py-2 text-slate-300">Posición <strong className="ml-1 text-slate-100">{pod.resultType==='empate'?'Empate':result.position}</strong></p><p className="px-3 py-2 text-slate-300">Kills <strong className="ml-1 text-slate-100">{result.kills}</strong></p></div>:<p className="border-t border-slate-700 px-3 py-2 text-xs text-slate-400">Resultados pendientes.</p>}</section>})}</div>}{editable && <form onSubmit={save} className="mt-3 space-y-4"><label className="block text-xs">Tipo de resultado<select value={resultType} onChange={event=>setResultType(event.target.value as NonNullable<Pod['resultType']>)} className={field}><option value="normal">Victoria normal</option><option value="combo">Victoria por combo</option><option value="empate">Empate</option></select></label>{isTie && <p className="rounded-md bg-slate-900 px-3 py-2 text-xs text-slate-300">La cantidad de puntos por persona en empates se configura</p>}<div className="grid gap-3">{pod.playerIds.map(playerId => <section className="overflow-hidden rounded-lg border border-slate-700 bg-slate-900" key={`${playerId}-${resultType}`}><h5 className="flex items-center justify-between gap-3 px-4 py-3 text-sm font-semibold"><span>{names[playerId]}</span>{isTie&&<button type="button" aria-pressed={deadPlayers.has(playerId)} title={deadPlayers.has(playerId)?'Marcar como vivo':'Marcar como muerto'} onClick={()=>toggleDead(playerId)} className={`rounded-md p-1.5 ${deadPlayers.has(playerId)?'bg-red-800 text-white':'text-slate-400 hover:bg-slate-800 hover:text-red-300'}`}><Skull size={17} /></button>}</h5><div className="grid grid-cols-2 border-t border-slate-700"><label className="border-r border-slate-700 p-3 text-xs font-semibold text-slate-300">Posición{isTie ? <input disabled value="Empate" type="text" className="mt-2 w-full rounded-md border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 opacity-60" /> : <input required min="1" max={pod.playerIds.length} name={`position-${playerId}`} defaultValue={pod.results?.find(r=>r.playerId===playerId)?.position ?? ''} type="number" className="mt-2 w-full rounded-md border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" />}</label><label className="p-3 text-xs font-semibold text-slate-300">Kills{isTie ? <input disabled value="0" type="text" className="mt-2 w-full rounded-md border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 opacity-60" /> : <input required min="0" name={`kills-${playerId}`} defaultValue={pod.results?.find(r=>r.playerId===playerId)?.kills ?? 0} type="number" className="mt-2 w-full rounded-md border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" />}</label></div></section>)}</div>{message && <Notice error={message.includes('Completa')}>{message}</Notice>}<button disabled={readOnly} className={primary}>Guardar resultado</button></form>}</div> }
function Standings() { const tournament = Current(); const { id } = useParams(); const rows = useTournaments().standingsFor(id!); const opponentHelp='Suma de los puntos obtenidos por las personas contra quienes jugaste.'; return <section className={panel}><h2 className="text-xl font-bold">Clasificación</h2><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-b border-slate-700 text-slate-400"><tr><th className="p-2">#</th><th className="p-2">Nombre</th><th className="p-2">Puntos</th><th className="p-2">Victorias</th><th className="p-2"><span className="inline-flex items-center gap-1">Fuerza de oponentes<span title={opponentHelp} aria-label={opponentHelp} className="cursor-help text-amber-300"><Info size={15} strokeWidth={2}/></span></span></th><th className="p-2">Kills</th><th className="p-2">Rondas</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-slate-800" key={row.player.id}><td className="p-2 font-bold text-amber-300">{row.rank}</td><td className="p-2">{row.player.name}{!row.player.active && <span className="ml-2 text-xs text-slate-500">Retirado</span>}</td><td className="p-2 font-bold">{row.points}</td><td className="p-2">{row.wins}</td><td className="p-2">{row.opponentStrength}</td><td className="p-2">{row.kills}</td><td className="p-2">{row.roundsPlayed}</td></tr>)}</tbody></table></div>{!tournament.rounds.length && <p className="mt-4 text-sm text-slate-400">La clasificación se llenará al guardar resultados.</p>}</section> }

function Settings() { const tournament = Current(); const { id } = useParams(); const { updateTournament } = useTournaments(); const [message,setMessage] = useState(''); const [pendingUpdate,setPendingUpdate]=useState<Partial<Tournament>>(); const [statusAction,setStatusAction]=useState<'finalizar'|'reabrir'>(); function commit(patch:Partial<Tournament>){updateTournament(id!,patch);setMessage('Configuración guardada; la clasificación se recalculó desde los resultados.')} function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const plannedRounds = Number(form.get('rounds')); if (!Number.isInteger(plannedRounds) || plannedRounds < tournament.rounds.length || plannedRounds < 1) return setMessage(`Las rondas planificadas deben ser un entero de al menos ${Math.max(1,tournament.rounds.length)}.`); const scoring = Object.fromEntries(['first','second','third','fourth','tie'].map(key => [key, Number(form.get(key))])) as unknown as ScoringRules; if(Object.values(scoring).some(value=>!Number.isInteger(value)||value<0)) return setMessage('Los puntos deben ser enteros no negativos.'); const patch={ name: String(form.get('name')).trim(), format: String(form.get('format')).trim(), plannedRounds, isPublic: true, scoring }; if (tournament.rounds.some(r=>r.pods.some(p=>p.results?.length))){setPendingUpdate(patch);return}commit(patch) } const canFinish = !tournament.rounds.some(round => round.status !== 'completada'); return <section className="grid gap-5 lg:grid-cols-3"><form onSubmit={save} className={`${panel} space-y-4 lg:col-span-2`}><h2 className="text-xl font-bold">Configuración del torneo</h2>{message && <Notice error={message.includes('deben') || message.includes('puntos')}>{message}</Notice>}<div className="grid gap-3 sm:grid-cols-2"><label className="text-sm">Nombre<input required name="name" defaultValue={tournament.name} className={field}/></label><label className="text-sm">Formato<input required name="format" defaultValue={tournament.format} className={field}/></label><label className="text-sm">Rondas planificadas<input required type="number" min="1" name="rounds" defaultValue={tournament.plannedRounds} className={field}/></label></div><fieldset><legend className="font-bold">Puntuación</legend><div className="mt-2 space-y-2">{[['first','Primer lugar'],['second','Segundo lugar'],['third','Tercer lugar'],['fourth','Cuarto lugar'],['tie','Empate (jugador vivo)']].map(([key,label])=><label className="flex items-center justify-between gap-4 text-xs" key={key}><span>{label}</span><input className="w-28 rounded-md border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" name={key} min="0" type="number" defaultValue={tournament.scoring[key as keyof ScoringRules]}/></label>)}</div></fieldset><button disabled={tournament.status === 'finalizado'} className={primary}>Guardar cambios</button></form><aside className={panel}><h2 className="font-bold">Estado</h2><p className="mt-2 text-sm text-slate-300">Finalizar bloquea las ediciones. Puede reabrirse mediante confirmación.</p>{tournament.status === 'finalizado' ? <button className="mt-4 rounded-lg border border-amber-400 px-3 py-2 text-sm text-amber-300" onClick={() => setStatusAction('reabrir')}>Reabrir torneo</button> : <button disabled={!canFinish} className={`${primary} mt-4`} onClick={() => setStatusAction('finalizar')}>Finalizar torneo</button>}{!canFinish && <p className="mt-2 text-xs text-red-300">Completa la ronda activa antes de finalizar.</p>}</aside>{pendingUpdate && <ConfirmModal title="Guardar configuración" description="Cambiar las reglas recalculará la clasificación con los resultados ya guardados." confirmLabel="Guardar cambios" onClose={() => setPendingUpdate(undefined)} onConfirm={() => { commit(pendingUpdate); setPendingUpdate(undefined) }} />}{statusAction && <ConfirmModal title={statusAction==='finalizar'?'Finalizar torneo':'Reabrir torneo'} description={statusAction==='finalizar'?'El torneo quedará en solo lectura.':'El torneo volverá a permitir cambios.'} confirmLabel={statusAction==='finalizar'?'Finalizar torneo':'Reabrir torneo'} onClose={() => setStatusAction(undefined)} onConfirm={() => { updateTournament(id!,{status:statusAction==='finalizar'?'finalizado':'activo'}); setStatusAction(undefined) }} />}</section> }
function PublicView() { const { slug } = useParams(); const [tournament,setTournament]=useState<Tournament>(); const [loading,setLoading]=useState(true); useEffect(()=>{let active=true;void loadPublicTournament(slug??'').then(data=>{if(active)setTournament(data)}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[slug]); if(loading)return <div className="min-h-screen bg-slate-950 p-8 text-slate-300">Cargando ronda…</div>; if(!tournament)return <div className="min-h-screen bg-slate-950 p-8 text-red-300">Esta vista publica no está disponible.</div>; const round=tournament.rounds.at(-1); const names=Object.fromEntries(tournament.players.map(player=>[player.id,player.name])); return <main className="min-h-screen bg-slate-950 px-4 py-8"><div className="mx-auto max-w-4xl"><p className="text-xs font-bold tracking-[.16em] text-amber-300">INFORMACIÓN DEL TORNEO</p><h1 className="mt-1 text-3xl font-black">{tournament.name}</h1><p className="mt-1 text-slate-300">{tournament.format}</p>{round?<section className={`${panel} mt-7`}><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><h2 className="text-xl font-bold">Ronda {round.number}</h2><Badge>{round.status}</Badge></div><RoundTimer round={round} /></div><div className="mt-5 grid gap-4 md:grid-cols-2">{round.pods.map(pod=><article className="rounded-lg border border-slate-700 bg-slate-950 p-4" key={pod.id}><h3 className="font-bold text-amber-300">Mesa {pod.number}</h3><div className="mt-3 grid gap-3">{pod.playerIds.map(playerId=>{const result=pod.results?.find(item=>item.playerId===playerId);return <section className="overflow-hidden rounded-lg border border-slate-700 bg-slate-900" key={playerId}><h4 className="px-4 py-3 text-sm font-semibold">{names[playerId]}</h4><div className="grid grid-cols-2 border-t border-slate-700 text-sm"><p className="border-r border-slate-700 px-4 py-3"><span className="block text-xs font-semibold text-slate-400">Posición</span><strong className="mt-1 block">{pod.resultType==='empate'?'Empate':result?.position ?? '—'}</strong></p><p className="px-4 py-3"><span className="block text-xs font-semibold text-slate-400">Kills</span><strong className="mt-1 block">{result?.kills ?? '—'}</strong></p></div></section>})}</div></article>)}</div></section>:<section className={`${panel} mt-7 text-slate-300`}>Las mesas aparecerán cuando el organizador genere la primera ronda.</section>}</div></main> }

export { Home }

function AdminRoute() {
  const { configured, user, loading, isAdmin } = useAuth()

  if (!configured) return <Navigate to="/" replace />
  if (loading) return <Layout><p className="text-sm text-slate-300">Verificando permisos de administración…</p></Layout>
  if (!user) return <Navigate to="/login" replace />
  if (!isAdmin) return <Navigate to="/dashboard" replace />
  return <AdminDashboard />
}

const displayDate = (value: string) => {
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat('es-CR', { dateStyle: 'medium' }).format(date)
}
const roleLabel = (role: AppRole) => role === 'super_admin' ? 'Super administrador' : role === 'admin' ? 'Administrador' : 'Organizador'

function AdminDashboard() {
  const { user, isSuperAdmin } = useAuth()
  const [overview, setOverview] = useState<AdminOverview>()
  const [error, setError] = useState<string>()
  const [refreshing, setRefreshing] = useState(false)
  const [changingRole, setChangingRole] = useState<string>()
  const [managedUsers, setManagedUsers] = useState<ManagedUser[]>([])
  const [editingUser, setEditingUser] = useState<ManagedUser>()
  const [profileSearch, setProfileSearch] = useState('')
  const [tournamentSearch, setTournamentSearch] = useState('')
  const [adminTab, setAdminTab] = useState<'accounts' | 'tournaments' | 'players' | 'details'>('accounts')

  const refresh = async () => {
    setRefreshing(true)
    try {
      setOverview(await loadAdminOverview())
      setError(undefined)
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'No se pudo cargar la información administrativa.')
    } finally {
      setRefreshing(false)
    }
  }

  const changeRole = async (profileId: string, role: AssignableRole) => {
    setChangingRole(profileId)
    try {
      await updateProfileRole(profileId, role)
      await refresh()
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'No se pudo cambiar el rol.')
    } finally {
      setChangingRole(undefined)
    }
  }

  useEffect(() => { void refresh() }, [])
  const refreshManagedUsers = async () => { try { setManagedUsers(await listManagedUsers()); } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudieron cargar los perfiles editables.') } }
  useEffect(() => { if (isSuperAdmin) void refreshManagedUsers() }, [isSuperAdmin])
  const removeProfile = async (target: ManagedUser) => { if (!window.confirm(`Eliminar la cuenta de ${target.displayName}? También se eliminarán sus torneos. Esta acción no se puede deshacer.`)) return; try { await deleteManagedUser(target.id); await Promise.all([refresh(), refreshManagedUsers()]) } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo eliminar la cuenta.') } }

  const profilesById = new Map(overview?.profiles.map(profile => [profile.id, profile]))
  const playerCount = overview?.tournaments.reduce((total, tournament) => total + tournament.playerCount, 0) ?? 0
  const activeTournaments = overview?.tournaments.filter(tournament => tournament.status === 'activo').length ?? 0
  const accountProfiles = overview?.profiles.filter(profile => isSuperAdmin || profile.role !== 'super_admin') ?? []
  const visibleProfiles = accountProfiles.filter(profile => `${profile.displayName} ${profile.role}`.toLocaleLowerCase().includes(profileSearch.toLocaleLowerCase()))
  const visibleTournaments = overview?.tournaments.filter(tournament => `${tournament.name} ${tournament.format} ${profilesById.get(tournament.ownerId)?.displayName ?? ''}`.toLocaleLowerCase().includes(tournamentSearch.toLocaleLowerCase())) ?? []

  return <Layout><div className="mb-6 flex flex-wrap items-start justify-between gap-4"><div><p className="inline-flex items-center gap-2 text-sm font-semibold text-amber-300"><ShieldCheck size={16} />ACCESO RESTRINGIDO</p><h1 className="mt-1 text-3xl font-black">Administración</h1><p className="mt-2 max-w-2xl text-sm text-slate-300">Vista global de la aplicación. Solo un super admin puede cambiar roles.</p></div><button type="button" className="inline-flex items-center gap-2 rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-50" disabled={refreshing} onClick={() => void refresh()}><RefreshCw size={16} className={refreshing ? 'animate-spin' : ''} />{refreshing ? 'Actualizando…' : 'Actualizar'}</button></div>{error&&<section className="mb-5 rounded-xl border border-red-700 bg-red-950 p-4 text-sm text-red-300">{error}</section>}<section className="mb-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><AdminMetric icon={<Users size={19} />} label="Cuentas" value={overview ? accountProfiles.length : '—'} /><AdminMetric icon={<ShieldCheck size={19} />} label="Acceso admin" value={overview?.profiles.filter(profile => profile.role === 'admin').length ?? '—'} /><AdminMetric icon={<Trophy size={19} />} label="Torneos activos" value={overview ? activeTournaments : '—'} /><AdminMetric icon={<Database size={19} />} label="Jugadores registrados" value={overview ? playerCount : '—'} /></section>{!overview&&!error&&<p className="text-sm text-slate-300">Cargando información de Supabase…</p>}{overview&&<><nav className="mb-7 flex gap-1 overflow-x-auto rounded-lg border border-slate-700 bg-slate-900 p-1">{([["accounts","Cuentas"],["tournaments","Torneos"],["players","Jugadores activos"],["details","Datos completos"]] as const).map(([tab,label])=><button key={tab} type="button" onClick={()=>setAdminTab(tab)} className={`whitespace-nowrap rounded-md px-3 py-2 text-sm ${adminTab===tab ? "bg-amber-400 font-bold text-slate-950" : "hover:bg-slate-800"}`}>{label}</button>)}</nav><div className={adminTab === 'accounts' ? '' : 'hidden'}><section className={`${panel} mb-7 overflow-hidden p-0`}><div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-700 px-5 py-4"><div><h2 className="text-xl font-black">Cuentas</h2></div><div className="flex items-center gap-2"><input value={profileSearch} onChange={event=>setProfileSearch(event.target.value)} className="w-52 rounded-lg border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" placeholder="Buscar cuenta" /><span className="text-sm text-slate-400">{accountProfiles.length} en total</span></div></div><div className="max-h-96 overflow-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-slate-700 bg-slate-800 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3 font-semibold">Organizador</th><th className="px-5 py-3 font-semibold">Rol</th><th className="px-5 py-3 font-semibold">Registro</th><th className="px-5 py-3 font-semibold">ID</th><th className="px-5 py-3 font-semibold">Acciones</th></tr></thead><tbody>{visibleProfiles.map(profile=><tr key={profile.id} className="border-b border-slate-700 last:border-0"><td className="px-5 py-3 font-semibold">{profile.displayName}</td><td className="px-5 py-3">{isSuperAdmin&&profile.id!==user?.id?<select aria-label={`Cambiar rol de ${profile.displayName}`} value={profile.role} disabled={changingRole===profile.id} onChange={event=>void changeRole(profile.id,event.target.value as AssignableRole)} className="rounded-md border border-slate-500 bg-slate-950 px-2 py-1 text-xs font-semibold disabled:cursor-not-allowed disabled:opacity-50"><option value="organizer">Organizador</option><option value="admin">Administrador</option></select>:<span className={profile.role !== 'organizer' ? 'rounded-md bg-amber-400 px-2 py-1 text-xs font-bold text-slate-950' : 'rounded-md bg-slate-800 px-2 py-1 text-xs font-semibold'}>{roleLabel(profile.role)}</span>}</td><td className="px-5 py-3 text-slate-300">{displayDate(profile.createdAt)}</td><td className="max-w-44 truncate px-5 py-3 font-mono text-xs text-slate-400" title={profile.id}>{profile.id}</td><td className="px-5 py-3">{isSuperAdmin&&profile.id!==user?.id&&managedUsers.find(managed=>managed.id===profile.id)?<div className="flex gap-2"><button type="button" className="rounded-md border border-slate-500 px-2 py-1 text-xs font-semibold hover:bg-slate-800" onClick={()=>setEditingUser(managedUsers.find(managed=>managed.id===profile.id))}>Editar</button><button type="button" className="rounded-md bg-red-700 px-2 py-1 text-xs font-bold text-white hover:bg-red-600" onClick={()=>void removeProfile(managedUsers.find(managed=>managed.id===profile.id)!)}>Eliminar</button></div>:<span className="text-slate-400">—</span>}</td></tr>)}{visibleProfiles.length===0&&<tr><td colSpan={5} className="px-5 py-5 text-slate-400">No hay perfiles registrados.</td></tr>}</tbody></table></div></section>{isSuperAdmin&&<SuperAdminUserManagement />}</div><div className={adminTab === 'tournaments' ? '' : 'hidden'}><section className={`${panel} overflow-hidden p-0`}><div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-700 px-5 py-4"><div><h2 className="text-xl font-black">Torneos</h2></div><div className="flex items-center gap-2"><input value={tournamentSearch} onChange={event=>setTournamentSearch(event.target.value)} className="w-52 rounded-lg border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" placeholder="Buscar torneo" /><span className="text-sm text-slate-400">{overview.tournaments.length} en total</span></div></div><div className="max-h-96 overflow-auto"><table className="w-full min-w-[780px] text-left text-sm"><thead className="border-b border-slate-700 bg-slate-800 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3 font-semibold">Torneo</th><th className="px-5 py-3 font-semibold">Organizador</th><th className="px-5 py-3 font-semibold">Estado</th><th className="px-5 py-3 font-semibold">Participantes</th><th className="px-5 py-3 font-semibold">Rondas</th><th className="px-5 py-3 font-semibold">Visibilidad</th><th className="px-5 py-3 font-semibold">Acciones</th></tr></thead><tbody>{visibleTournaments.map(tournament=><tr key={tournament.id} className="border-b border-slate-700 last:border-0"><td className="px-5 py-3"><strong className="block">{tournament.name}</strong><span className="text-xs text-slate-400">{tournament.format} · {displayDate(tournament.createdAt)}</span></td><td className="px-5 py-3 text-slate-300">{profilesById.get(tournament.ownerId)?.displayName ?? 'Organizador eliminado'}</td><td className="px-5 py-3"><Badge>{tournament.status}</Badge></td><td className="px-5 py-3 tabular-nums">{tournament.playerCount}</td><td className="px-5 py-3 tabular-nums">{tournament.roundCount}</td><td className="px-5 py-3"><span className={tournament.isPublic ? 'text-emerald-300' : 'text-slate-400'}>{tournament.isPublic ? 'Público' : 'Privado'}</span></td><td className="px-5 py-3">{isSuperAdmin?<Link to={`/tournaments/${tournament.id}`} className="rounded-md border border-slate-500 px-2 py-1 text-xs font-semibold hover:bg-slate-800">Gestionar</Link>:<span className="text-slate-400">—</span>}</td></tr>)}{visibleTournaments.length===0&&<tr><td colSpan={7} className="px-5 py-5 text-slate-400">No hay torneos registrados.</td></tr>}</tbody></table></div></section></div><div className={adminTab === 'players' ? '' : 'hidden'}><SuperAdminPlayerManagement /></div><div className={adminTab === 'details' ? '' : 'hidden'}><AdminDataInspector /></div>{editingUser&&<UserProfileModal user={editingUser} onClose={()=>setEditingUser(undefined)} onSaved={()=>{void refresh();void refreshManagedUsers();setEditingUser(undefined)}} />}</>}</Layout>
}

function AdminMetric({ icon, label, value }: { icon: React.ReactNode; label: string; value: number | string }) {
  return <article className={panel}><div className="flex items-center gap-2 text-amber-300">{icon}<span className="text-sm font-semibold">{label}</span></div><strong className="mt-3 block text-3xl font-black tabular-nums">{value}</strong></article>
}

function AdminDataInspector() {
  const [tournaments, setTournaments] = useState<Tournament[]>()
  const [error, setError] = useState<string>()
  const [search, setSearch] = useState('')

  useEffect(() => {
    let active = true
    void loadAllTournaments().then(data => { if (active) setTournaments(data) }).catch(reason => { if (active) setError(reason instanceof Error ? reason.message : 'No se pudo cargar el detalle de los torneos.') })
    return () => { active = false }
  }, [])

  const visibleTournaments = tournaments?.filter(tournament => `${tournament.name} ${tournament.format}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()))
  return <section className={`${panel} mt-7`}><div><h2 className="text-xl font-black">Datos completos</h2><p className="mt-1 text-sm text-slate-300">Consulta de solo lectura de cada torneo, con reglas, jugadores, rondas, mesas y resultados. No incluye credenciales ni datos de Authentication.</p></div>{error&&<p className="mt-4 text-sm text-red-300">{error}</p>}{!tournaments&&!error&&<p className="mt-4 text-sm text-slate-300">Cargando detalle…</p>}<input value={search} onChange={event=>setSearch(event.target.value)} className="mt-4 w-full rounded-lg border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" placeholder="Buscar detalle de torneo" /><div className="mt-4 max-h-[34rem] space-y-3 overflow-y-auto pr-1">{visibleTournaments?.map(tournament=><details key={tournament.id} className="rounded-lg border border-slate-700 bg-slate-950 p-4"><summary className="cursor-pointer font-semibold"><span>{tournament.name}</span><span className="ml-2 text-sm font-normal text-slate-400">{tournament.players.length} jugadores · {tournament.rounds.length} rondas</span></summary><pre className="mt-4 max-h-96 overflow-auto rounded-md bg-slate-900 p-4 text-xs leading-relaxed text-slate-300">{JSON.stringify(tournament, null, 2)}</pre></details>)}</div></section>
}

function SuperAdminUserManagement() {
  const { user } = useAuth()
  const [users, setUsers] = useState<ManagedUser[]>()
  const [error, setError] = useState<string>()
  const [busy, setBusy] = useState(false)
  const [search, setSearch] = useState('')
  const load = async () => { try { setUsers(await listManagedUsers()); setError(undefined) } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudieron cargar las cuentas.') } }
  useEffect(() => { void load() }, [])
  const matchingUsers = users?.filter(managed => `${managed.displayName} ${managed.email} ${managed.role}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()))
  const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setBusy(true); try { await createManagedUser({ displayName: String(form.get('displayName')).trim(), email: String(form.get('email')).trim(), password: String(form.get('password')), role: String(form.get('role')) as AssignableRole }); event.currentTarget.reset(); await load() } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo crear la cuenta.') } finally { setBusy(false) } }
  const update = async (event: FormEvent<HTMLFormElement>, id: string) => { event.preventDefault(); const form = new FormData(event.currentTarget); setBusy(true); try { await updateManagedUser(id, { displayName: String(form.get('displayName')).trim(), email: String(form.get('email')).trim(), password: String(form.get('password')) || undefined, role: String(form.get('role')) as AssignableRole }); await load() } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo actualizar la cuenta.') } finally { setBusy(false) } }
  const remove = async (target: ManagedUser) => { if (!window.confirm(`Eliminar la cuenta de ${target.displayName}? También se eliminarán sus torneos. Esta acción no se puede deshacer.`)) return; setBusy(true); try { await deleteManagedUser(target.id); await load() } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo eliminar la cuenta.') } finally { setBusy(false) } }
  return <section className={`${panel} mt-7`}><div><p className="text-sm font-semibold text-amber-300">SUPER ADMIN</p><h2 className="mt-1 text-xl font-black">Gestión de usuarios</h2></div>{error&&<p className="mt-4 text-sm text-red-300">{error}</p>}<form onSubmit={create} className="mt-5 grid gap-3 rounded-lg border border-slate-700 bg-slate-950 p-4 md:grid-cols-4"><input required name="displayName" className={field} placeholder="Nombre" /><input required name="email" type="email" className={field} placeholder="correo@ejemplo.com" /><input required name="password" minLength={6} type="password" className={field} placeholder="Contraseña temporal" /><select name="role" defaultValue="organizer" className={field}><option value="organizer">Organizador</option><option value="admin">Administrador</option></select><button disabled={busy} className={`${primary} md:col-span-4`}>Crear usuario</button></form><input value={search} onChange={event=>setSearch(event.target.value)} className="mt-4 w-full rounded-lg border border-slate-600 bg-slate-950 px-3 py-2 text-sm text-slate-100 outline-none focus:border-amber-400" placeholder="Buscar usuario" /><div className="mt-3 max-h-[34rem] space-y-3 overflow-y-auto pr-1">{matchingUsers?.map(managed=>managed.id===user?.id?<article key={managed.id} className="rounded-lg border border-slate-700 p-4"><strong>{managed.displayName}</strong><span className="ml-2 text-sm text-amber-300">Super admin protegido</span></article>:<form key={managed.id} onSubmit={event=>void update(event,managed.id)} className="grid gap-3 rounded-lg border border-slate-700 p-4 md:grid-cols-5"><input required name="displayName" defaultValue={managed.displayName} className={field} /><input required name="email" type="email" defaultValue={managed.email} className={field} /><input name="password" minLength={6} type="password" className={field} placeholder="Nueva contraseña (opcional)" /><select name="role" defaultValue={managed.role} className={field}><option value="organizer">Organizador</option><option value="admin">Administrador</option></select><div className="flex items-end gap-2"><button disabled={busy} className={primary}>Guardar</button><button disabled={busy} type="button" className="rounded-lg bg-red-700 px-3 py-2 text-sm font-bold text-white hover:bg-red-600 disabled:opacity-50" onClick={()=>void remove(managed)}>Eliminar</button></div></form>)}{matchingUsers?.length===0&&<p className="text-sm text-slate-400">No hay cuentas que coincidan.</p>}</div></section>
}

function SuperAdminPlayerManagement() {
  const { isSuperAdmin } = useAuth()
  const [tournaments, setTournaments] = useState<Tournament[]>()
  const [search, setSearch] = useState('')
  const [error, setError] = useState<string>()
  const [busy, setBusy] = useState(false)
  const load = async () => { try { setTournaments(await loadAllTournaments()); setError(undefined) } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudieron cargar los jugadores.') } }
  useEffect(() => { void load() }, [])
  const players = (tournaments ?? []).flatMap(tournament => tournament.players.filter(player => player.active).map(player => ({ tournament, player }))).filter(({ player, tournament }) => `${player.name} ${tournament.name}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()))
  if (!isSuperAdmin) return <section className={`${panel} mt-7`}><div><h2 className="text-xl font-black">Jugadores activos</h2><p className="mt-1 text-sm text-slate-300">Consulta de jugadores activos por torneo.</p></div>{error&&<p className="mt-4 text-sm text-red-300">{error}</p>}<input value={search} onChange={event=>setSearch(event.target.value)} className={`${field} mt-4`} placeholder="Buscar jugador o torneo" /><div className="mt-3 max-h-96 space-y-2 overflow-y-auto pr-1">{players.map(({ tournament, player })=><article key={player.id} className="flex items-center justify-between gap-3 rounded-lg border border-slate-700 p-3"><strong>{player.name}</strong><span className="text-sm text-slate-400">{tournament.name}</span></article>)}{tournaments&&players.length===0&&<p className="text-sm text-slate-400">No hay jugadores activos que coincidan.</p>}</div></section>
  const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const tournament = tournaments?.find(item => item.id === String(form.get('tournamentId'))); const name = String(form.get('name')).trim(); if (!tournament || !name) return; setBusy(true); try { await insertPlayers(tournament.id, [{ id: uid(), name, active: true, tieBreaker: tournament.players.length + 1 }]); event.currentTarget.reset(); await load() } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo crear el jugador.') } finally { setBusy(false) } }
  const update = async (event: FormEvent<HTMLFormElement>, player: Tournament['players'][number]) => { event.preventDefault(); const name = String(new FormData(event.currentTarget).get('name')).trim(); if (!name) return; setBusy(true); try { await persistPlayer({ ...player, name }); await load() } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo actualizar el jugador.') } finally { setBusy(false) } }
  const remove = async (player: Tournament['players'][number]) => { if (!window.confirm(`Eliminar a ${player.name}?`)) return; setBusy(true); try { await removeRemotePlayer(player.id); await load() } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se puede eliminar un jugador con participaciones registradas.') } finally { setBusy(false) } }
  return <section className={`${panel} mt-7`}><div><p className="text-sm font-semibold text-amber-300">SUPER ADMIN</p><h2 className="mt-1 text-xl font-black">Jugadores activos</h2><p className="mt-1 text-sm text-slate-300">Crea cada jugador dentro de un torneo y administra sus datos desde aquí.</p></div>{error&&<p className="mt-4 text-sm text-red-300">{error}</p>}<form onSubmit={create} className="mt-4 grid gap-3 rounded-lg border border-slate-700 bg-slate-950 p-4 md:grid-cols-3"><select required name="tournamentId" className={field} defaultValue=""><option value="" disabled>Selecciona un torneo</option>{tournaments?.map(tournament=><option key={tournament.id} value={tournament.id}>{tournament.name}</option>)}</select><input required name="name" className={field} placeholder="Nombre del jugador" /><button disabled={busy} className={primary}>Crear jugador</button></form><input value={search} onChange={event=>setSearch(event.target.value)} className={`${field} mt-4`} placeholder="Buscar jugador o torneo" /><div className="mt-3 max-h-96 space-y-3 overflow-y-auto pr-1">{players.map(({ tournament, player })=><form key={player.id} onSubmit={event=>void update(event,player)} className="grid gap-3 rounded-lg border border-slate-700 p-4 md:grid-cols-[1fr_1fr_auto]"><div><span className="block text-xs text-slate-400">{tournament.name}</span><input required name="name" defaultValue={player.name} className={field} /></div><span className="self-end text-sm text-emerald-300">Activo</span><div className="flex items-end gap-2"><button disabled={busy} className={primary}>Guardar</button><button disabled={busy} type="button" className="rounded-lg bg-red-700 px-3 py-2 text-sm font-bold text-white hover:bg-red-600" onClick={()=>void remove(player)}>Eliminar</button></div></form>)}{tournaments&&players.length===0&&<p className="text-sm text-slate-400">No hay jugadores activos que coincidan.</p>}</div></section>
}

function UserProfileModal({ user, onClose, onSaved }: { user: ManagedUser; onClose: () => void; onSaved: () => void }) {
  const [error, setError] = useState<string>()
  const [busy, setBusy] = useState(false)
  const save = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    setBusy(true)
    try {
      await updateManagedUser(user.id, { displayName: String(form.get('displayName')).trim(), email: String(form.get('email')).trim(), password: String(form.get('password')) || undefined, role: String(form.get('role')) as AssignableRole })
      onSaved()
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'No se pudo actualizar el perfil.')
    } finally {
      setBusy(false)
    }
  }
  return <Modal title={`Editar perfil: ${user.displayName}`} description="Deja la contraseña vacía para conservarla." onClose={onClose}><form onSubmit={save} className="space-y-4">{error&&<p className="text-sm text-red-300">{error}</p>}<label className="block text-sm font-medium">Nombre<input required name="displayName" defaultValue={user.displayName} className={field} /></label><label className="block text-sm font-medium">Correo<input required name="email" type="email" defaultValue={user.email} className={field} /></label><label className="block text-sm font-medium">Nueva contraseña<input name="password" minLength={6} type="password" className={field} /></label><label className="block text-sm font-medium">Rol<select name="role" defaultValue={user.role === 'admin' ? 'admin' : 'organizer'} className={field}><option value="organizer">Organizador</option><option value="admin">Administrador</option></select></label><div className="flex justify-end gap-3"><button type="button" className="rounded-lg border border-slate-500 px-4 py-2 text-sm font-semibold hover:bg-slate-800" onClick={onClose}>Cancelar</button><button disabled={busy} className={primary}>{busy ? 'Guardando…' : 'Guardar cambios'}</button></div></form></Modal>
}
